export function enhanceProjectsPage(fragment: string): string {
  let html = fragment;

  // 1. Add Deep Drop Reel & Custom Long Line Spools to Marine Haulers section if not present
  if (!html.includes("/deep-drop-reel")) {
    const haulerMatch = html.match(/(Blue Thunder Manual & Hydraulic Line Hauler[\s\S]*?<\/div>\s*<\/div>\s*<\/div>\s*<\/div>)/);
    if (haulerMatch) {
      const extraHaulerCards = `
                <div class="col-lg-4 col-md-6 project-block show2">
                    <div class="inner-box">
                        <div class="image" style="background: #fff; border-radius: 4px; overflow: hidden; box-shadow: 0 8px 24px rgba(0,0,0,0.08);">
                            <img src="/assets/images/new-products/deep-drop-reel-main.jpeg" alt="Deep Drop Fishing Reel Model NI13031984" style="width: 100%; height: 260px; object-fit: contain; padding: 12px; display: block;" />
                        </div>
                        <div class="text-overlay test-desc">
                            <div class="link">
                                <a href="/deep-drop-reel" class="theme-btn btn-style-one goToProd"><span>
                                        <h3 style="color: whitesmoke; font-size: 1.25em; font-weight: bold; text-transform: uppercase;">Deep Drop Fishing Reel</h3>
                                    </span></a>
                            </div>
                        </div>
                    </div>
                </div>
                <div class="col-lg-4 col-md-6 project-block show2">
                    <div class="inner-box">
                        <div class="image" style="background: #fff; border-radius: 4px; overflow: hidden; box-shadow: 0 8px 24px rgba(0,0,0,0.08);">
                            <img src="/assets/images/new-products/longline-spool-main.jpeg" alt="Custom Long Line Spools" style="width: 100%; height: 260px; object-fit: contain; padding: 12px; display: block;" />
                        </div>
                        <div class="text-overlay test-desc">
                            <div class="link">
                                <a href="/longline-spools" class="theme-btn btn-style-one goToProd"><span>
                                        <h3 style="color: whitesmoke; font-size: 1.25em; font-weight: bold; text-transform: uppercase;">Custom Long Line Spools</h3>
                                    </span></a>
                            </div>
                        </div>
                    </div>
                </div>`;
      html = html.replace(haulerMatch[0], haulerMatch[0] + extraHaulerCards);
    }
  }

  // 2. Add Seawater Heat Exchangers to Inboard Marine Engines section if not present
  if (!html.includes("/heat-exchangers")) {
    const engineMatch = html.match(/(RECONDITION Marine Engine[\s\S]*?<\/div>\s*<\/div>\s*<\/div>\s*<\/div>)/);
    if (engineMatch) {
      const extraEngineCard = `
                <div class="col-lg-4 col-md-6 project-block show2">
                    <div class="inner-box">
                        <div class="image" style="background: #fff; border-radius: 4px; overflow: hidden; box-shadow: 0 8px 24px rgba(0,0,0,0.08);">
                            <img src="/assets/images/new-products/cooler-1.png" alt="Seawater Heat Exchangers & Oil Coolers" style="width: 100%; height: 260px; object-fit: contain; padding: 12px; display: block;" />
                        </div>
                        <div class="text-overlay test-desc">
                            <div class="link">
                                <a href="/heat-exchangers" class="theme-btn btn-style-one goToProd"><span>
                                        <h3 style="color: whitesmoke; font-size: 1.25em; font-weight: bold; text-transform: uppercase;">Seawater Heat Exchangers</h3>
                                    </span></a>
                            </div>
                        </div>
                    </div>
                </div>`;
      html = html.replace(engineMatch[0], engineMatch[0] + extraEngineCard);
    }
  }

  // 3. Update preview grid images to high-res new product images
  html = html.replace(
    "/assets/images/HYDRAULIC MOTORS/HYDRAULIC MOTORS-20.jpeg",
    "/assets/images/new-products/hydraulic-motor-1.jpeg"
  );
  html = html.replace(
    "/assets/images/projects-mainPage-slide-image/product_slide_Img05.jpeg",
    "/assets/images/new-products/hydraulic-pumps-1.png"
  );
  html = html.replace(
    "/assets/images/SEALS & O RINGS/WhatsApp Image 2026-06-04 at 4.44.29 PM.jpeg",
    "/assets/images/new-products/seals-display.jpeg"
  );
  html = html.replace(
    "/assets/images/Prod-imgs/spiral-gaskets/sg1.jpg",
    "/assets/images/new-products/spiral-gasket-steam.jpeg"
  );

  // 4. Add SS Hydraulic Fittings, CNC Engineering & Heat Exchangers into preview grid
  if (!html.includes("/stainless-steel-fittings")) {
    const extraPreviewCards = `
                    <article class="product-preview-card hidden2">
                        <h5 class="product-preview-card__title">SS Hydraulic Fittings</h5>
                        <div class="product-preview-card__image">
                            <img src="/assets/images/new-products/fittings-ss-1.png" alt="Stainless steel hydraulic fittings">
                        </div>
                        <div class="product-preview-card__actions">
                            <a href="/stainless-steel-fittings" class="product-preview-card__button">Go To Page ></a>
                        </div>
                    </article>
                    <article class="product-preview-card hidden2">
                        <h5 class="product-preview-card__title">CNC Machining & Fabrication</h5>
                        <div class="product-preview-card__image">
                            <img src="/assets/images/new-products/lathe.png" alt="Manual and CNC Engineering">
                        </div>
                        <div class="product-preview-card__actions">
                            <a href="/cnc-engineering" class="product-preview-card__button">Go To Page ></a>
                        </div>
                    </article>
                    <article class="product-preview-card hidden2">
                        <h5 class="product-preview-card__title">Seawater Heat Exchangers</h5>
                        <div class="product-preview-card__image">
                            <img src="/assets/images/new-products/cooler-1.png" alt="Seawater Heat Exchangers">
                        </div>
                        <div class="product-preview-card__actions">
                            <a href="/heat-exchangers" class="product-preview-card__button">Go To Page ></a>
                        </div>
                    </article>`;

    const wpRegex = /(<a href="\/water-pump"[\s\S]*?<\/article>)/;
    if (wpRegex.test(html)) {
      html = html.replace(wpRegex, "$1" + extraPreviewCards);
    }
  }

  return html;
}

